  { id: 'char-l2-m-35-2', type: 'mystery', characterId: 'jethro', category: 'Personnages', difficulty: 'expert', answer: 'Jéthro', clues: ['Il accueille Moïse après sa fuite d’Égypte.','Ce personnage reconnut la supériorité de Jéhovah après avoir entendu ce qu’il avait fait pour Israël. Il se réjouit avec Moïse et offrit un sacrifice au vrai Dieu.','Ce personnage accueillit Moïse alors qu’il était fugitif.'], explanation: 'Ce personnage accueillit Moïse alors qu’il était fugitif.', reference: 'Exode 2:16-22' },
  { id: 'char-l2-m-36-1', type: 'mystery', characterId: 'zipporah', category: 'Personnages', difficulty: 'hard', answer: 'Séphora', clues: ['Ce personnage était la fille de Jéthro, l’épouse de Moïse et la mère de ses fils Guershom et Éliézer.','Madian et sur la route vers l’Égypte.','Réactivité'], explanation: 'Ce personnage accepta de quitter Madian pour suivre Moïse.', reference: 'Exode 2:21-22' },
  { id: 'char-l2-m-36-2', type: 'mystery', characterId: 'zipporah', category: 'Personnages', difficulty: 'expert', answer: 'Séphora', clues: ['Elle rencontre Moïse près d’un puits de Madiân.','Lors d’une situation grave sur le chemin de l’Égypte, Ce personnage circoncit rapidement son fils conformément à l’exigence divine. Le récit montre l’importance qu’elle accordait à cette obligation.','Ce personnage accepta de quitter Madian pour suivre Moïse.'], explanation: 'Ce personnage accepta de quitter Madian pour suivre Moïse.', reference: 'Exode 2:21-22' },
  { id: 'char-l2-m-37-1', type: 'mystery', characterId: 'korah', category: 'Personnages', difficulty: 'hard', answer: 'Qorah', clues: ['Ce personnage était un Lévite, cousin de Moïse et d’Aaron, qui contesta leur autorité avec Dathan, Abiram et 250 autres hommes.','Désert, dans le camp d’Israël.','Zèle religieux'], explanation: 'Ce personnage possédait déjà une position honorable parmi les Lévites mais voulut davantage d’autorité.', reference: 'Nombres 16:1-50' },
  { id: 'char-l2-m-37-2', type: 'mystery', characterId: 'korah', category: 'Personnages', difficulty: 'expert', answer: 'Qorah', clues: ['Il accuse Moïse et Aaron de s’élever au-dessus de la congrégation.','Ce personnage contesta l’autorité que Jéhovah avait confiée à Moïse et Aaron. Sa rébellion eut de graves conséquences pour lui et ses partisans.','Ce personnage possédait déjà une position honorable parmi les Lévites mais voulut davantage d’autorité.'], explanation: 'Ce personnage possédait déjà une position honorable parmi les Lévites mais voulut davantage d’autorité.', reference: 'Nombres 16:1-50' },
  { id: 'char-l2-m-38-1', type: 'mystery', characterId: 'balaam', category: 'Personnages', difficulty: 'hard', answer: 'Balaam', clues: ['Ce personnage était un homme de Mésopotamie que Balak engagea pour maudire Israël. Jéhovah l’empêcha finalement de prononcer une malédiction contre son peuple.','Mésopotamie puis territoire de Moab.','Connaissance prophétique'], explanation: 'Ce personnage savait que Jéhovah ne permettait pas de maudire Israël.', reference: 'Nombres 22:1-41' },
  { id: 'char-l2-m-38-2', type: 'mystery', characterId: 'balaam', category: 'Personnages', difficulty: 'expert', answer: 'Balaam', clues: ['Balak lui demande de maudire Israël.','Ce personnage reçut des instructions de Jéhovah et fut contraint de bénir Israël au lieu de le maudire. Cependant, la Bible le présente aussi comme un homme qui a laissé l’avidité influencer sa conduite.','Ce personnage savait que Jéhovah ne permettait pas de maudire Israël.'], explanation: 'Ce personnage savait que Jéhovah ne permettait pas de maudire Israël.', reference: 'Nombres 22:1-41' },
  { id: 'char-l2-m-39-1', type: 'mystery', characterId: 'balak', category: 'Personnages', difficulty: 'hard', answer: 'Balak', clues: ['Ce personnage était roi de Moab lorsque les Israélites approchaient de la Terre promise. Il chercha à faire maudire Israël par Balaam.','Moab, à l’est du Jourdain.','Organisation'], explanation: 'Ce personnage laissa la peur guider ses décisions.', reference: 'Nombres 22:1-41' },
  { id: 'char-l2-m-39-2', type: 'mystery', characterId: 'balak', category: 'Personnages', difficulty: 'expert', answer: 'Balak', clues: ['Il voit la puissance d’Israël et craint pour Moab.','Ce personnage craignait Israël et chercha à faire prononcer une malédiction contre lui. Ses efforts échouèrent parce que Jéhovah ne permit pas à Balaam de maudire son peuple.','Ce personnage laissa la peur guider ses décisions.'], explanation: 'Ce personnage laissa la peur guider ses décisions.', reference: 'Nombres 22:1-41' },
  { id: 'char-l2-m-40-1', type: 'mystery', characterId: 'eli', category: 'Personnages', difficulty: 'hard', answer: 'Éli', clues: ['Ce personnage était grand prêtre et juge en Israël. Il servit au sanctuaire de Shilo et fut le responsable de Samuel pendant son enfance.','Silo, au sanctuaire d’Israël.','Attention au service'], explanation: 'Ce personnage servait au sanctuaire et forma le jeune Samuel dans le service de Jéhovah.', reference: '1 Samuel 1:9-28' },
  { id: 'char-l2-m-40-2', type: 'mystery', characterId: 'eli', category: 'Personnages', difficulty: 'expert', answer: 'Éli', clues: ['Il sert comme prêtre à Shilo.','Ce personnage servait comme prêtre à Silo et enseigna à Samuel comment répondre lorsqu’il entendait l’appel de Jéhovah. Malgré cela, il fut repris parce qu’il n’avait pas suffisamment discipliné ses fils.','Ce personnage servait au sanctuaire et forma le jeune Samuel dans le service de Jéhovah.'], explanation: 'Ce personnage servait au sanctuaire et forma le jeune Samuel dans le service de Jéhovah.', reference: '1 Samuel 1:9-28' }
